using System;using System.IO;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Mismo.Gameplay.Combat;using Mismo.Gameplay.Player.Equipment;using Mismo.Gameplay.Player.Movement;
public static class StaminaComboChecks {
 public static void Run(){var log=new List<string>();Directory.CreateDirectory("output/combo-stamina");Action<bool,string> check=(ok,msg)=>{if(!ok)throw new Exception(msg);log.Add("PASS "+msg);};try{
 var actor=new GameObject();var combo=actor.AddComponent<BasicSwordCombo>();var h=new GameObject();h.transform.SetParent(actor.transform);h.AddComponent<BoxCollider>();var hit=h.AddComponent<AttackHitbox>();typeof(AttackHitbox).GetMethod("Awake",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(hit,null);combo.Configure(hit);
 var stamina=actor.AddComponent<Stamina>();var settings=ScriptableObject.CreateInstance<StaminaSettings>();stamina.Configure(settings);Action reset=()=>typeof(Stamina).GetMethod("Awake",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(stamina,null);reset();
 var ability=ScriptableObject.CreateInstance<AbilityDefinition>();ability.staminaCost=10;ability.comboSteps=new[]{new ComboStep(),new ComboStep(),new ComboStep()};
 check(combo.RequestAttack(ability)&&stamina.Current==90,"First step costs once");
 for(int i=1;i<=2;i++){combo.Tick(.4f);check(combo.RequestAttack()&&stamina.Current==100-i*10,"Queue does not spend");check(!combo.RequestAttack()&&stamina.Current==100-i*10,"Repeated input does not double-charge");combo.Tick(.4f);hit.EvaluateImpact();combo.Tick(.07f);check(combo.CurrentStepIndex==i&&stamina.Current==100-(i+1)*10,"Following step costs once");}
 combo.Cancel();reset();combo.RequestAttack(ability);combo.Tick(.4f);combo.RequestAttack();combo.Cancel();check(stamina.Current==90,"Cancelled queued step is free");
 reset();combo.RequestAttack(ability);combo.Tick(.4f);combo.RequestAttack();stamina.TrySpend(85);combo.Tick(.4f);hit.EvaluateImpact();combo.Tick(.07f);check(!combo.IsActive&&combo.IsRecovering&&stamina.Current==5,"Insufficient stamina at transition ends chain without a free attack");combo.Tick(1);check(!combo.IsRecovering,"Failed transition does not leave combo stuck");check(!combo.RequestAttack(ability)&&stamina.Current==5,"Unaffordable first step refused");ability.staminaCost=0;check(combo.RequestAttack(ability)&&stamina.Current==5,"Zero-cost combo remains supported");
 File.WriteAllLines("output/combo-stamina/checks.txt",log);EditorApplication.Exit(0);
 }catch(Exception e){log.Add("FAIL "+e);File.WriteAllLines("output/combo-stamina/checks.txt",log);EditorApplication.Exit(1);}}}
